// Temporary probe: simulate replay 'D' then player continuation,
// printing live-cell positions and lock point.
import { getLogic } from './src/components/Game/logic.ts'
import { hatetrisRotationSystem } from './src/rotation-systems/hatetris-rotation-system.ts'
import { hatetrisAi } from './src/enemy-ais/hatetris-ai.ts'

const props = {
  bar: 4,
  wellDepth: 20,
  wellWidth: 10,
  rotationSystem: hatetrisRotationSystem,
  ai: hatetrisAi
}

const logic = getLogic(props)
let state = await logic.getFirstWellState({
  mode: 'PLAYING',
  replay: [],
  wellStates: [],
  wellStateId: 0,
  ...props
})

const liveCells = (state) => {
  const { piece } = state
  if (piece === null) return []
  const orientation = hatetrisRotationSystem.rotations[piece.id][piece.o]
  const cells = []
  for (let y2 = 0; y2 < orientation.yDim; y2++) {
    for (let x2 = 0; x2 < orientation.xDim; x2++) {
      if ((orientation.rows[y2] & (1 << x2)) !== 0) {
        cells.push(`${piece.x + orientation.xMin + x2},${piece.y + orientation.yMin + y2}`)
      }
    }
  }
  return cells.sort().join(' ')
}

const landedCount = (state) =>
  state.core.well.reduce((n, row) => n + (row === 0 ? 0 : [...row.toString(2)].filter(c => c === '1').length), 0)

console.log('spawn:', state.piece.id, state.piece.o, 'x', state.piece.x, 'y', state.piece.y)
console.log('live@spawn:', liveCells(state))

state = await logic.handleMove(state, 'D')
console.log('live after replay D:', state.piece.y, liveCells(state))

for (let i = 1; ; i++) {
  const prevLanded = landedCount(state)
  state = await logic.handleMove(state, 'D')
  const nowLanded = landedCount(state)
  if (state.mode === 'GAME_OVER') { console.log('game over at player D', i); break }
  if (nowLanded > prevLanded || state.piece.y < 0) {
    console.log(`locked after player D #${i}; landed=${nowLanded}; new piece:`, state.piece && `${state.piece.id} o=${state.piece.o} x=${state.piece.x} y=${state.piece.y}`)
    console.log('live after lock:', state.piece && liveCells(state))
    break
  }
}

