// Temporary probe: simulate replay 'D' then player continuation,
// printing live-cell positions and lock point.
import { getLogic } from './src/components/Game/logic.ts'
import hatetrisRotationSystem from './src/rotation-systems/hatetris-rotation-system.ts'
import { hatetrisAi } from './src/enemy-ais/hatetris-ai.ts'

const props = {
  bar: 4,
  wellDepth: 20,
  wellWidth: 10,
  rotationSystem: hatetrisRotationSystem
}

const logic = getLogic(props)
const enemy = { shortDescription: '', buttonDescription: '', ai: hatetrisAi }

const firstWellState = await logic.getFirstWellState({ enemy })
let state = {
  enemy,
  mode: 'PLAYING',
  wellStateId: 0,
  wellStates: [firstWellState],
  replay: []
}

const liveCells = (wellState) => {
  const { piece } = wellState
  if (piece === null) return []
  const orientation = hatetrisRotationSystem.rotations[piece.id][piece.o]
  const cells = []
  for (let y2 = 0; y2 < orientation.yDim; y2++) {
    for (let x2 = 0; x2 < orientation.xDim; x2++) {
      if ((orientation.rows[y2] & (1 << x2)) !== 0) {
        cells.push(`${piece.x + orientation.xMin + x2},${piece.y + orientation.yMin + y2}`)
      }
    }
  }
  return cells.sort().join(' ')
}

const landedCount = (wellState) =>
  wellState.core.well.reduce((n, row) => n + [...row.toString(2)].filter(c => c === '1').length, 0)

console.log('spawn:', state.wellStates[0].piece.id, 'o', state.wellStates[0].piece.o, 'x', state.wellStates[0].piece.x, 'y', state.wellStates[0].piece.y)
console.log('live@spawn:', liveCells(state.wellStates[0]))

// The replay step
state = await logic.handleMove(state, 'D')
console.log('wellStateId', state.wellStateId, 'replay', state.replay)
console.log('live after replay D:', state.wellStates[1].piece.y, liveCells(state.wellStates[1]))

// Player continuation: Down presses until lock
for (let i = 1; ; i++) {
  const prevLanded = landedCount(state.wellStates[state.wellStateId])
  state = await logic.handleMove(state, 'D')
  const ws = state.wellStates[state.wellStateId]
  const nowLanded = landedCount(ws)
  if (state.mode === 'GAME_OVER') { console.log('game over at player D', i); break }
  if (nowLanded > prevLanded || ws.piece.y < 0) {
    console.log(`locked after player D #${i}; landed=${nowLanded}; new piece:`, ws.piece && `${ws.piece.id} o=${ws.piece.o} x=${ws.piece.x} y=${ws.piece.y}`)
    console.log('live after lock:', ws.piece && liveCells(ws))
    break
  }
}

